import{_ as b,o as l,c as i,ag as o}from"./chunks/framework.QfQ7DfGu.js";const h=JSON.parse('{"title":"LoongArch其他文档","description":"","frontmatter":{"title":"LoongArch其他文档","outline":"deep"},"headers":[],"relativePath":"docs-la/others-ref.md","filePath":"docs-la/others-ref.md"}'),e={name:"docs-la/others-ref.md"};function t(a,r,n,L,s,A){return l(),i("div",null,[...r[0]||(r[0]=[o('<h1 id="其他的参考文档" tabindex="-1">其他的参考文档 <a class="header-anchor" href="#其他的参考文档" aria-label="Permalink to &quot;其他的参考文档&quot;">​</a></h1><h2 id="_1-《龙架构与操作系统底层的交互》" tabindex="-1"><strong>1. 《龙架构与操作系统底层的交互》</strong> <a class="header-anchor" href="#_1-《龙架构与操作系统底层的交互》" aria-label="Permalink to &quot;**1. 《龙架构与操作系统底层的交互》**&quot;">​</a></h2><p>此文档主要是介绍龙架构底层如何与操作系统内核配合。详细的介绍了龙架构一些重点内容，结合代码例子。</p><p>可以说是对龙架构官方手册的进一步解释与说明。</p><p>目的： <strong>读完这个文档，你自己可以很快的给一个操作系统内核增加LoongArch的支持。</strong></p><p>内容整体如下：</p><ul><li><ol><li>本文档是对LoongArch架构与底层操作系统的紧密相关文档，类似于对linux内核的目录arch/loongarch下做个说明。</li></ol></li><li><ol start="2"><li>特权态指令的一些说明，结合模拟器做出伪代码的说明。</li></ol></li><li><ol start="3"><li>DMW的使用与说明，以及使用的场合说明。</li></ol></li><li><ol start="4"><li>LA的内存管理系统，包括TLB相关寄存器的初始化，LA的TLB refill指令，tlb的使用等等（这部分也是难点）</li></ol></li><li><ol start="5"><li>LA的中断系统，如何更加采用一个合理的中断安排等</li></ol></li><li><ol start="6"><li>LoongArch的新世界与旧世界，我们为什么要采用新世界，如何使用新世界等等</li></ol></li><li><ol start="7"><li>LoongArch ABI2.0的介绍与使用，伪代码实例等等</li></ol></li><li><ol start="8"><li>如何调试一个内核，以一个内核为例，如何使用上游的qemu以及gdb支持调试操作系统等等。</li></ol></li></ul><p>文档在<a href="https://os-kernel-with-loong64-doc.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">这里</a></p><p>下面是真个文档的目录，可以查找具体的小节。</p><ol><li>准备工作<br> 1.1. 前言<br> 1.1.1. 仓库地址<br> 1.1.2. 维护说明<br> 1.1.3. 更新说明<br> 1.2. 工具链说明<br> 1.2.1. GCC<br> 1.2.2. LLVM<br> 1.2.3. Rust<br> 1.3. 模拟器<br> 1.3.1. QEMU<br> 1.3.2. LA_EMU<br> 1.4. 操作系统编译<br> 1.4.1. LoongNix<br> 1.4.2. Deepin<br> 1.4.3. AOSC(安同)<br> 1.4.4. Linux kernel<br> 1.5. LICENSE说明<br> 1.5.1. 声明</li><li>工具链<br> 2.1. GCC<br> 2.1.1. GCC的相关概念<br> 2.1.2. 交叉编译器<br> 2.1.3. 常见的类别组合<br> 2.1.4. 如何编译交叉编译器<br> 2.1.5. 常用的参数与选项<br> 2.2. Binutils<br> 2.2.1. GNU Binutils的相关说明<br> 2.2.2. ld链接器<br> 2.2.3. 如何正确的使用readelf<br> 2.2.4. objdump<br> 2.2.5. objcopy<br> 2.3. Rust<br> 2.3.1. Rust的概念<br> 2.3.2. LoongArch支持的target有哪些<br> 2.3.3. 与LoongArch相关的具体参数那些<br> 2.3.4. 简单的例子说明如何编译成LA架构的EXE文件<br> 2.4. 内嵌的函数与指令包装<br> 2.4.1. GCC<br> 2.4.2. LLVM<br> 2.4.3. Rust<br> 2.5. 汇编代码与链接脚本<br> 2.5.1. 与LoongArch相关的汇编指令<br> 2.5.2. 链接脚本<br> 2.6. 一些常用的库函数<br> 2.6.1. GLIBC<br> 2.6.2. MUSL<br> 2.6.3. memcpy<br> 2.6.4. memmove<br> 2.6.5. memset</li><li>特权态指令<br> 3.1. CSR寄存器<br> 3.2. CSR指令<br> 3.2.1. CSRRD指令<br> 3.2.2. CSRWR指令<br> 3.2.3. CSRXCHG指令<br> 3.3. IOCSR指令<br> 3.3.1. IOCSRRD指令<br> 3.3.2. IOCSRWR指令<br> 3.4. CPUCFG 指令<br> 3.5. CACOP 指令<br> 3.6. TLB 与页表指令<br> 3.6.1. TLB 相关指令<br> 3.6.2. 页表查找指令<br> 3.6.3. 应用示例<br> 3.7. ERTN指令<br> 3.8. IDLE指令<br> 3.9. SysCALL指令</li><li>内存管理<br> 4.1. LoongArch的地址管理<br> 4.1.1. 直接地址翻译模式<br> 4.1.2. 映射地址翻译模式<br> 4.1.3. 存储访问的类型<br> 4.2. LoongArch的TLB结构<br> 4.2.1. 逻辑组织结构<br> 4.2.2. TLB的表项（以CPU的视觉）<br> 4.3. TLB的管理<br> 4.3.1. TLB的一些概念区分<br> 4.3.2. TLB相关的指令<br> 4.3.3. TLB相关的CSR<br> 4.3.4. TLB相关的例外<br> 4.3.5. CPU内部TLB查找流程示例<br> 4.4. 直接映射翻译模式<br> 4.4.1. CSR.DMW[0-3]<br> 4.4.2. 操作系统中如何使用<br> 4.5. 多级页表结构<br> 4.5.1. 设计背景与必要性<br> 4.5.2. LoongArch的多级页表结构<br> 4.5.3. 内存中的页表表项（Kernel视角）<br> 4.5.4. 页表的遍历<br> 4.6. 从内存中的页表表项到CPU中的TLB<br> 4.6.1. TLBRefill (Softeware PTW)<br> 4.6.2. Hardware PTW<br> 4.6.3. 页表的刷新<br> 4.7. Kernel与MMU<br> 4.7.1. 地址翻译相关的初始化<br> 4.7.2. 如何从直接地址翻译模式到映射地址翻译模式<br> 4.7.3. 如何建立虚拟地址到物理地址的映射关系<br> 4.7.4. 页表的遍历页表<br> 4.7.5. 情况1. 如果TLB中没有映射<br> 4.7.6. 情况2. 如果页表项的V=0<br> 4.7.7. 情况3. 如果写操作页表项D=0<br> 4.7.8. 情况4. 如果权限不合法<br> 4.7.9. 如果使能硬件PTW</li><li>中断与异常系统<br> 5.1. 中断<br> 5.1.1. 线中断<br> 5.1.2. 消息中断<br> 5.1.3. 中断的优先级<br> 5.1.4. 中断的打开与关闭<br> 5.1.5. 中断的入口地址<br> 5.1.6. 中断的处理流程<br> 5.2. 例外<br> 5.2.1. 例外的优先级<br> 5.2.2. 例外的入口地址<br> 5.2.3. 例外的处理过程<br> 5.3. Kernel与异常<br> 5.3.1. 异常的入口地址选择<br> 5.3.2. 异常的初始化<br> 5.3.3. 异常发生时，CPU做了什么<br> 5.4. 特殊异常的处理<br> 5.4.1. 定时器中断<br> 5.4.2. 系统调用<br> 5.4.3. 非对齐访问</li><li>SMP多核系统<br> 6.1. SMP对称多核处理器<br> 6.1.1. SMP多核处理器概述<br> 6.1.2. SMP的核心特征<br> 6.1.3. SMP的技术原理<br> 6.1.4. SMP的优缺点<br> 6.1.5. SMP的应用场景<br> 6.1.6. SMP与其他架构的对比<br> 6.1.7. SMP的发展趋势<br> 6.1.8. 总结<br> 6.2. SMP与LoongArch<br> 6.3. IPI中断<br> 6.3.1. 按地址访问模式(MMIO)<br> 6.3.2. 按配置寄存器指令模式(IOCSR)<br> 6.3.3. 多核中断处理流程<br> 6.4. IOCSR指令与多核通信<br> 6.5. SMP的初始化<br> 6.5.1. CPU-0的初始化<br> 6.6. Linux中SMP的处理（与架构相关）<br> 6.6.1. 多核的同步<br> 6.6.2. 多核的页表处理</li><li>程序二进制接口<br> 7.1. 旧世界<br> 7.2. 新旧世界的区分<br> 7.2.1. 新世界与旧世界的区别<br> 7.3. 新旧世界的底层差异<br> 7.3.1. 导言<br> 7.3.2. 内核<br> 7.3.3. 用户态<br> 7.4. 寄存器使用约定<br> 7.4.1. 使用说明<br> 7.5. 函数调用规约<br> 7.6. C语言与机器类型<br> 7.6.1. 数据类型<br> 7.6.2. 栈帧的排布<br> 7.6.3. 优化对栈帧的影响<br> 7.6.4. longjump和setjump<br> 7.7. ELF头 (Header)<br> 7.8. ELF 可重定位<br> 7.8.1. 可重定位类型（Relocation Type）<br> 7.8.2. 动态链接（dynamic link）<br> 7.8.3. 静态链接（static link）<br> 7.9. 代码模型(Code Model)</li><li>调试方法与技巧<br> 8.1. LoongArch最小debug环境搭建<br> 8.1.1. 制作 Linux RamDisk<br> 8.1.2. QEMU 参数说明<br> 8.1.3. QEMU 调试教程<br> 8.2. GDB使用<br> 8.2.1. 交叉编译环境中的GDB<br> 8.2.2. 常见的GDB命令示例<br> 8.2.3. 调试指令常见失效状况</li><li>平台相关<br> 9.1. QEMU<br> 9.1.1. Virt<br> 9.1.2. 设备<br> 9.2. 3A5000芯片<br> 9.2.1. 芯片参数<br> 9.2.2. 芯片架构<br> 9.2.3. 地址空间<br> 9.3. 3A6000芯片<br> 9.3.1. 芯片参数<br> 9.3.2. 芯片架构<br> 9.4. 2k3000芯片<br> 9.4.1. 芯片参数<br> 9.5. 2k1000LA芯片<br> 9.5.1. 芯片参数<br> 9.5.2. 芯片架构<br> 9.5.3. 芯片功能<br> 9.5.4. 地址空间<br> 9.6. 2k0500芯片<br> 9.6.1. 芯片架构<br> 9.6.2. 芯片架构<br> 9.6.3. 芯片架构<br> 9.6.4. 芯片功能<br> 9.6.5. 地址空间<br> 9.6.6. 中断配置<br> 9.7. 2k0300芯片<br> 9.7.1. 芯片参数<br> 9.7.2. 芯片架构<br> 9.7.3. 芯片功能<br> 9.7.4. 地址空间<br> 9.7.5. 中断配置及路由</li><li>高级应用：SMID与向量指令<br> 10.1. TODO</li><li>高级应用：LVZ与虚拟化扩展<br> 11.1. TODO</li><li>FAQ<br> 12.1. FAQ-25</li></ol><h2 id="_2-《la32r指令集学习指导手册》" tabindex="-1">2. 《LA32R指令集学习指导手册》 <a class="header-anchor" href="#_2-《la32r指令集学习指导手册》" aria-label="Permalink to &quot;2. 《LA32R指令集学习指导手册》&quot;">​</a></h2><p>龙架构（LoongArch，后文简称LA）指令集包含三个主要分支，即64位分支（LoongArch64，后文简称LA64）、32位分支（LoongArch32，后文简称LA32）和32位精简版分支（LoongArch32 Reduced，后文简称LA32R）。</p><p>其中LA32R定位为用于教学科研，具有小而精的设计特点。其用户态整数指令仅有50余条，在CPU硬件不实现浮点指令的情况下也能运行各种软件，同时核心态定义了特权等级、例外与中断和存储管理三部分内容，支持操作系统运行，在实现了存储管理中的TLB MMU情况下还可运行Linux操作系统。</p><p>目前各上游社区和龙芯开源社区上的工作基本上都是针对LA64的，同时各类龙架构相关的教材、参考书籍也基本上都是围绕LA64进行介绍的。尽管说LA32R和LA64的设计风格是一致的，指令码是相同的，但是让初学者仅依据LA32R指令集手册并参考LA64相关学习资料来摸索着掌握LA32R，确实存在一定的难度且发生理解偏差。因此我们萌生了编写一个LA32R指令集学习指导手册的想法，希望能给初学者提供一些便利。</p><p>整本手册在内容安排上还是偏向软件开发者视角多一些。如果您的需求更多偏向于CPU硬件设计开发，那么可以参考《CPU设计实战：LoongArch版》这本书。本手册中我们试图从软件开发者视角出发，针对指令集中的技术内容“为什么这样设计”、“软硬件如何协同”谈一些我们的理解。同时为了控制整本手册的篇幅，在行文的详略尺度方面，我们会侧重于指令架构相关的内容，而指令架构无关的本领域公共基础知识，如ELF文件格式、链接与装载的共性概念、GDB调试命令、Linux内核中公共代码的处理流程等，我们会提及但不会展开。相关知识建议读者们自行查阅资料。我们也会在讲述到相关内容时推荐一些参考材料供读者进一步阅读。</p><p>我们希望本手册的读者事先已了解过至少一个指令集，而且最好是RISC型的指令集。如果没有的话，强烈建议通过学习一些经典教材来建立这方面的认识。推荐《Computer Organization and Design: The Hardware Software Interface》这本教材。第4版或第5版就可以，MIPS版、ARMv8版或者RISC-V版也都可以。指令集的基础共性知识已很成熟，不同指令集间都是相通的。这本教材讲授的内容很丰富，时间有限的话可以只看其中介绍指令集的章节。</p><p>本文档目录如下：</p><ul><li>LA32R中的用户态整型指令 <ul><li>LA32R的机器语言与汇编语言表达</li><li>算术逻辑移位类指令</li><li>数据传输类指令</li><li>分支跳转类指令</li><li>用LL/SC指令构建基本同步原语</li><li>其它用户态指令</li></ul></li><li>LA32R汇编编程简介 <ul><li>LA32R汇编编程学习环境介绍</li><li>常用汇编器指示</li><li>LA32R汇编器支持的伪指令汇总</li><li>寄存器使用约定</li><li>函数调用约定</li><li>进程虚拟地址空间布局规范</li><li>栈帧布局</li><li>汇编编程示例</li></ul></li></ul><p>文档在线阅读的地址<a href="https://la32r-study-note.readthedocs.io/zh-cn/latest/" target="_blank" rel="noreferrer">在这里</a></p>',19)])])}const p=b(e,[["render",t]]);export{h as __pageData,p as default};
